      def feature(f)
        id=f.data_id;v=f.value
        param=PARAMS[id] || id.to_s
        case f.code
        when 11 then 'Damage received: '+(BS2Modules.element_name(id).to_s.empty? ? 'element '+id.to_s : BS2Modules.element_name(id))+' ×'+BS2Modules.num(v)
        when 12 then 'Debuff chance for '+param+' ×'+BS2Modules.num(v)
        when 13 then 'State chance for «'+named($data_states,id,'State')+'» ×'+BS2Modules.num(v)
        when 14 then 'Immune: '+named($data_states,id,'State')
        when 21 then param+' ×'+BS2Modules.num(v)
        when 22
          label=['Accuracy','Evasion','Critical chance','Critical evasion','Magic evasion','Magic reflection','Counterattack','HP regeneration','MP regeneration','TP regeneration'][id] || 'Extra parameter'
          label+': '+(v>=0 ? '+' : '')+BS2Modules.pct(v)+' (contribution)'
        when 23
          label=['Target rate','Guard effectiveness','Received healing','Item effectiveness','MP cost','TP gain','Physical damage received','Magic damage received','Floor damage','Experience gained'][id] || 'Special parameter'
          label+' ×'+BS2Modules.num(v)
        when 31 then 'Attack element: '+BS2Modules.element_name(id).to_s
        when 32 then 'Attack applies: '+named($data_states,id,'State')+'; contribution '+BS2Modules.pct(v)
        when 33 then 'Attack speed: '+BS2Modules.num(v)
        when 34 then 'Additional hits: '+BS2Modules.num(v)
        when 41 then 'Skill type granted: '+$data_system.skill_types[id].to_s
        when 42 then 'Skill type sealed: '+$data_system.skill_types[id].to_s
        when 43 then 'Skill granted: '+named($data_skills,id,'Skill')
        when 44 then 'Skill sealed: '+named($data_skills,id,'Skill')
        when 51 then 'Weapon type permitted: '+BS2Modules.weapon_type(id).to_s
        when 52 then 'Armor type permitted: '+BS2Modules.armor_type(id).to_s
        when 53 then 'Cannot unequip: '+Vocab.etype(id).to_s
        when 54 then 'Slot sealed: '+Vocab.etype(id).to_s
        when 55 then 'Slot type: '+(id==1 ? 'dual wield' : 'normal')
        when 61 then 'Extra action: independent chance '+BS2Modules.pct(v)
        when 62 then ['Auto battle','Guard stance','Substitute ally','Preserve TP'][id] || 'Special flag '+id.to_s
        when 63 then 'Collapse type: '+id.to_s
        when 64 then ['Fewer random encounters','No random encounters','No surprise attacks','More preemptive attacks','Double souls','Double drops'][id] || 'Party ability '+id.to_s
        else 'Additional property '+f.code.to_s+' / '+id.to_s+': '+BS2Modules.num(v)
        end
      end
      def special(object)
        note=object.note.to_s;lines=[]
        lines << 'Item use is sealed.' if note.include?('<アイテム封印>')
        lines << 'Full recovery does not remove this state.' if note.include?('[全回復無効ステート]')
        lines << 'Physical attacks bypass the normal hit check.' if note.include?('<物理絶対命中>')
        lines << 'Magical attacks bypass the normal hit check.' if note.include?('<魔法絶対命中>')
        note.scan(/<(HP|MP)回復(無効|反転):(\d+)>/) do |m|
          label=m[0]=='HP' ? 'HP' : 'MP'
          lines << 'Chance of '+(m[1]=='無効' ? 'blocking' : 'converting to damage')+' healing for '+label+': '+m[2]+'%.'
          lines << 'Applies to direct healing by skill or item.'
        end
        note.scan(/<反撃スキル\s+(\d+)>/) { |m| lines << 'Counterattack skill: '+named($data_skills,m[0].to_i,'Skill') }
        note.scan(/<全回避時スキル:(\d+)>/) { |m| lines << 'On complete evasion: '+named($data_skills,m[0].to_i,'Skill') }
        note.scan(/<スキル無効:(\d+)(?:,(\d+))?>/) { |m| lines << 'Skill has no effect: '+named($data_skills,m[0].to_i,'Skill')+'; chance '+(m[1] || '100')+'%.' }
        note.scan(/<強制自然解除時ステート:(\d+)>/) { |m| lines << 'On natural expiration: '+named($data_states,m[0].to_i,'State') }
        lines << 'Removed before the next action when the counter is 1.' if note.include?('<次の行動前に解除>')
        note.scan(/<フレーム再生=(-?\d+),(-?\d+),(-?\d+)>/) do |m|
          lines << 'Per state tick: HP '+m[0]+'%, MP '+m[1]+'%, TP '+m[2]+'%.'
        end
        # A note may include arbitrary event/script logic. Do not claim a complete
        # semantic explanation of it; every active state is still listed.
        lines << 'Special script rules may add to the properties below.' unless note.strip.empty?
        lines
      end
      def duration(actor,state)
        turns=hash_of(actor,:@state_turns)[state.id]
        timing=state.auto_removal_timing
        lines=[]
        case timing
        when 1 then lines << 'Action endings remaining: '+(turns.nil? ? '?' : turns.to_s)
        when 2 then lines << 'Turn endings remaining: '+(turns.nil? ? '?' : turns.to_s)
        when 3
          frames=hash_of(actor,:@state_frames)[state.id]
          lines << (state.auto_remove? ? 'Ticks remaining: '+turns.to_s : 'Ticks without automatic removal.')
          lines << 'Until next tick: '+frames.to_s+' internal frames.' unless frames.nil?
          lines << 'Tick interval: '+state.turn_frame.to_s+' internal frames; not seconds.'
        else lines << 'No automatic countdown.'
        end
        lines << 'Removed at battle end.' if state.remove_at_battle_end
        lines << 'Removal chance on damage: '+state.chance_by_damage.to_s+'%.' if state.remove_by_damage
        if state.remove_by_walking
          steps=hash_of(actor,:@state_steps)[state.id]
          lines << 'Steps remaining: '+(steps.nil? ? '?' : steps.to_s)
        end
        lines << 'Removed when actions become restricted.' if state.remove_by_restriction
        lines
      end
      def active(actor)
        rows=[]
        actor.states.each do |state|
          details=duration(actor,state)
          r=['Actions permitted.','Attacks an enemy without selection.','Attacks a random side.','Attacks an ally without selection.','Actions prohibited.'][state.restriction]
          details << r if state.restriction>0 && r
          details += special(state)+state.features.map { |f| feature(f) }
          details << 'The game did not retain the application source; it cannot be inferred from the name.'
          summary=details[0].sub('Action endings remaining: ','Actions: ').sub('Turn endings remaining: ','Turns: ').sub('No automatic countdown.','No countdown')
          rows << {:name=>BS2Modules.label(state,'State'),:summary=>summary,:details=>details,:kind=>:state,:id=>state.id}
        end
        buffs=actor.instance_variable_get(:@buffs) || []
        buffs.each_with_index do |level,id|
          next if level==0
          turns=hash_of(actor,:@buff_turns)[id]
          timing=defined?(ATB::BUFF_TURN_COUNT) && ATB::BUFF_TURN_COUNT==1 ? 'action endings' : 'turn endings'
          value=level*25
          rows << {:name=>PARAMS[id]+(level>0 ? ' +' : ' ')+value.to_s+'%',:summary=>'Level '+level.to_s+'; remaining '+turns.to_s,
            :details=>['Parameter change: '+value.to_s+'%.','Level: '+level.to_s,'Remaining '+timing+': '+turns.to_s,'The game did not retain the application source.'],:kind=>:buff,:id=>id}
        end
        cooldowns=hash_of($game_temp,:@cool_time)
        counts=cooldowns.has_key?(actor) ? cooldowns[actor] : {}
        counts.keys.sort.each do |id|
          count=counts[id];next unless count>0
          rows << {:name=>named($data_skills,id,'Skill'),:summary=>'Cooldown: '+count.to_s,:details=>['Cooldown: '+count.to_s,'Counter decreases at turn end.','This is the current counter, not future skipped turns.'],:kind=>:cooldown,:id=>id}
        end
        [ [actor,:@hzm_vxa_quickSkill_can_use_skill,$data_skills,'Instant skill'],
          [defined?(HZM_VXA::QuickSkill::ITEM_COUNT_PARTY) && HZM_VXA::QuickSkill::ITEM_COUNT_PARTY ? $game_party : actor,:@hzm_vxa_quickSkill_can_use_item,$data_items,'Instant item'] ].each do |owner,key,data,kind|
          list=owner.instance_variable_get(key)
          next unless list.is_a?(Array)
          list.uniq.each do |id|
            object=data[id];next unless object
            m=/\[hzm\](?:ターン消費無し|即発動|QuickSkill)\s*[:：]\s*(\d+)/.match(object.note)
            next unless m
            count=list.count(id);limit=[m[1].to_i,1].max
            rows << {:name=>BS2Modules.label(object),:summary=>'Instant: '+count.to_s+'/'+limit.to_s,
              :details=>[kind,'Used this turn: '+count.to_s+' of '+limit.to_s,owner==$game_party ? 'Limit shared by the party.' : 'Limit for this actor.'],:kind=>:quick,:id=>id}
          end
        end
        rows
      end
      def sources(actor)
        rows=[]
        objects=[['Actor',actor.actor],['Class',actor.class]]
        actor.equips.each_with_index { |object,i| objects << [Vocab.etype(actor.equip_slots[i]).to_s,object] if object }
        # States have their own active entries. Other feature providers remain
        # visible even when a future compatible script adds a provider.
        actor.feature_objects.each do |object|
          next if objects.any? { |x| x[1].equal?(object) } || object.is_a?(RPG::State)
          objects << ['Additional source',object]
        end
        objects.each do |label,object|
          next unless object
          details=[]
          if object.is_a?(RPG::EquipItem)
            object.params.each_with_index { |v,i| details << PARAMS[i]+': '+(v>0 ? '+' : '')+v.to_s if v!=0 }
            details << object.description.to_s unless object.description.to_s.empty?
          end
          details += object.features.map { |f| feature(f) }+special(object)
          details << 'No additional properties.' if details.empty?
          rows << {:name=>BS2Modules.label(object),:summary=>label,:details=>details,:kind=>:source,:object=>object}
        end
        rows
      end
